// eslint-disable-next-line @typescript-eslint/no-explicit-any
let ReactDOM17: any;
// eslint-disable-next-line @typescript-eslint/no-explicit-any
let ReactDOMClient: any;

import('react-dom/client')
  .then((module) => {
    ReactDOMClient = module;
  })
  .catch(() => import('react-dom'))
  .then((module) => {
    ReactDOM17 = module;
  });

/**
 * @internal
 * @param component -
 * @param element -
 */
export function safeReactDomRender(
  component: React.ReactNode,
  element: Element,
): void {
  if (ReactDOMClient && ReactDOMClient.createRoot) {
    const root = ReactDOMClient.createRoot(element);
    root.render(component);
  } else if (ReactDOM17 && ReactDOM17.render) {
    ReactDOM17.render(component, element);
  }
}
